def xargs(cmd: tuple[str, ...], varargs: Sequence[str], *, color: bool = False, target_concurrency: int = 1, _max_length: int = _get_platform_max_length(), **kwargs: Any) -> tuple[int, bytes]:
    """A simplified implementation of xargs.

    color: Make a pty if on a platform that supports it
    target_concurrency: Target number of partitions to run concurrently
    """

    import os
    import subprocess
    import shlex

    if color:
        import pty

    command = [cmd[0]] + [shlex.quote(arg) for arg in cmd[1:] + varargs]
    parts = [
        command[i:i + _max_length - len(cmd[0])] for i in range(0, len(command), _max_length - len(cmd[0]))
    ]

    if color:
        master, slave = pty.openpty()
    else:
        master, slave = os.pipe()

    processes = []
    for part in parts:
        p = subprocess.Popen(part, stdin=None, stdout=subprocess.PIPE, stderr=subprocess.PIPE, start_new_session=color)
        processes.append(p)

    outputs = []
    while processes:
        for p in list(processes):
            pid, status = p.poll()
            if pid is not None:
                processes.remove(p)
                outputs.append(p.stdout.read())

    if color:
        os.close(slave)
    else:
        os.close(master)

    return len(outputs), b''.join(outputs)

