def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    if sys.platform == 'win32':
        cmd = list(cmd)
        first_arg = cmd[0]
        if re.match(r'^#!', first_arg):
            if os.path.isabs(first_arg[2:].strip()):
                cmd[0] = first_arg[2:].strip()
            elif os.path.isabs(os.path.join(os.getcwd(), first_arg[2:].strip())):
                cmd[0] = os.path.join(os.getcwd(), first_arg[2:].strip())
            else:
                cmd[0] = os.path.join(sys.prefix, 'bin', first_arg[2:].strip())
        return tuple(cmd)
    return cmd

