from collections import OrderedDict

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """

    class _TTLCache:
        def __init__(self, maxsize, ttl, timer, typed):
            self.cache = OrderedDict()
            self.maxsize = maxsize
            self.ttl = ttl
            self.timer = timer
            self.typed = typed

        def __call__(self, func):
            def wrapper(*args, **kwargs):
                key = (func, args, tuple(kwargs.items())) if self.typed else (func, tuple(args), tuple(kwargs.items()))
                if key in self.cache:
                    expire, result = self.cache[key]
                    if self.timer() - expire < self.ttl:
                        return result
                    else:
                        del self.cache[key]
                else:
                    if len(self.cache) >= self.maxsize:
                        self.cache.popitem(last=False)

                result = func(*args, **kwargs)
                expire = self.timer()
                self.cache[key] = (expire, result)
                return result

            return wrapper

        def __sizeof__(self):
            return self.cache.__sizeof__()

    return _TTLCache(maxsize, ttl, timer, typed)
