    class _TTLCache(object):
        def __init__(self, maxsize, ttl, timer, typed):
            self.maxsize = maxsize
            self.ttl = ttl
            self.timer = timer
            self.cache = OrderedDict()
            self.cache_info = ShrinkableOrderedDict()
            self.typing = typed

        def __call__(self, func):
            if self.typing:
                key_type = get_function_type(func.__call__)
                val_type = get_function_type(func.__next__)
                cache_key = (key_type, val_type)
            else:
                cache_key = (func,)

            def wrapper(*args, **kwargs):
                nonlocal cache
                cache_key = cache_key + args + tuple(sorted(kwargs.items()))
                if cache_key in cache:
                    cache[cache_key] = (func(*args, **kwargs), self.timer())
                elif len(cache) < self.maxsize:
                    cache[cache_key] = (func(*args, **kwargs), self.timer())
                else:
                    cache.popitem(last=False)
                    cache[cache_key] = (func(*args, **kwargs), self.timer())

                return cache[cache_key][0]

            wrapper.cache_info = cache_info
            return wrapper

        def cache_clear(self):
            self.cache.clear()
            self.cache_info.clear()

        def cache_info(self):
            return cache_info

