    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """

    class _TTLCache(func_wrapper):
        def __init__(self):
            self.cache = {}
            self.expiry = {}

        def __call__(self, *args, **kwargs):
            key = args + tuple(kwargs.items())
            if key in self.cache:
                if timer() - self.expiry[key] < ttl:
                    return self.cache[key]
                else:
                    del self.cache[key]
                    del self.expiry[key]
            result = self.func(*args, **kwargs)
            if len(self.cache) >= maxsize:
                oldest_key = min(self.expiry, key=self.expiry.get)
                del self.cache[oldest_key]
                del self.expiry[oldest_key]
            self.cache[key] = result
            self.expiry[key] = timer()
            return result

    def wrapper(func):
        func_wrapper.cache_info = lambda: _TTLCache.cache_info
        func_wrapper.cache_clear = lambda: _TTLCache.cache_clear
        func_wrapper.cache_stats = lambda: _TTLCache.cache_stats
        return wraps(func)(wrapper)
