def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    """
    def decorator(func):
        cache = {} if typed else {}
        sentinel = object()

        def wrapper(*args, **kwds):
            key = args if typed else (args, tuple(kwds.items()))
            if key not in cache:
                cache[key] = func(*args, **kwds)
            return cache[key]

        @wraps(func)
        def memoized_func(*args, **kwds):
            if "__wrapped__" in wrap.__dict__:
                return wrap.__dict__["__wrapped__"](*args, **kwds)
            else:
                return wrapper(*args, **kwds)

        return memoized_func

    return decorator
