@classmethod
def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception.
    :param e: Any exception instance.
    :type e: Exception
    :param max_level: Maximum call stack level (default 30)
    :type max_level: int
    :param max_path_level: Maximum path level (default 5)
    :type max_path_level: int
    :return The exception readable string
    :rtype str
    """
    import traceback
    import os

    class FakeExc(object):

        def __init__(self, args):
            self.args = args

        def __str__(self):
            return ', '.join(map(repr, self.args))

    data = []
    seen = set()

    def fv(tb):
        result = traceback.extract_tb(tb, max_level=max_level)
        for file, line, funcname, text in result:
            if file not in seen:
                code = open(file).read().split('\n')
                idx = min(line - 1, len(code) - 1)
                line = code[idx]
                while line.strip() and line.strip() != 'except:':
                    if idx:
                        idx -= 1
                    else:
                        break
                    line = code[idx]
                filepath = os.path.abspath(os.path.realpath(file))
                if filepath.startswith('/'):
                    filepath = filepath[1:]
                while len(filepath) > max_path_level:
                    i = filepath.find('/', 1)
                    if i:
                        filepath = filepath[i:]
                data.append([filepath, str(line).strip(), funcname])
        seen.add(file)

    while e:
        data.append([e.__class__.__module__, str(e),(''.join(traceback.format_tb(e.__traceback__, max_level=max_level))).split('\n')])
        fv(e.__traceback__)
        e = e.__cause__

    # make one big line of output
    olddata = data[:]
    result = []
    while olddata:
        if not result:
            result.append(olddata.pop())
        oldest = result[-1]
        if oldest[0] in seen:
            result.pop()
            for d in olddata:
                if d[0] == oldest[0]:
                    oldest.update(d)
        else:
            seen.add(oldest[0])
    rv = []
    for d in result:
        rv.append('File "%s", line %s, in %s\n    %s' % tuple(d))
    return '\n'.join(rv)
