def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    min_classes = []
    for cls in classes:
        if all(issubclass(cls, base) for base in min_classes):
            continue
        for base in min_classes[:]:
            if issubclass(cls, base):
                min_classes.remove(base)
        min_classes.append(cls)
    return min_classes
