    if output is None:
        output = []

    for arg in sequence:
        if isinstance(arg, Declaration):
            for sub_arg in arg.args:
                _normalizeargs(sub_arg, output)
        elif isinstance(arg, tuple):
            for sub_arg in arg:
                _normalizeargs(sub_arg, output)
        elif isinstance(arg, Interface):
            output.append(arg)
