def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    import re
    from .errors import ValidationError

    errors = []

    label_key_regex = re.compile(r'^[a-zA-Z0-9_.-]{1,50}$')
    label_value_regex = re.compile(r'^[a-zA-Z0-9_.-]{1,50}$')

    for key, value in labels.items():
        if not isinstance(key, str):
            key_errors = {str(key): f"expected string or bytes-like object"}
            errors.append(key_errors)
            continue

        key_errors = {}
        if not label_key_regex.match(key):
            key_errors[key] = f"Label key '{key}' does not match the regex."
        if key_errors:
            errors.append(key_errors)

        if not isinstance(value, list):
            value_error = {"'".join(value): 'expected string or bytes-like object'}
            errors.append(value_error)
            continue

        value_errors = []
        for v in value:
            if not isinstance(v, str):
                value_errors.append(v)
        if value_errors:
            errors.append({"'".join(value_errors): 'expected string or bytes-like object'})

    if errors:
        raise ValidationError(errors)
