        if isinstance(value, list) or isinstance(value, dict):
            obs_dict[key] = generate_default_observer_schema_dict(value, False)
        else:
            obs_dict[key] = None

    if first_level:
        obs_dict['apiVersion'] = manifest_dict['apiVersion']
