def _explore_zipfile(zip_path):
    """Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    from collections import defaultdict
    import xml.etree.ElementTree as ET
    import zipfile

    def etree_to_dict(t):
        d = {t.tag: {} if t.attrib else None}
        children = list(t)
        if children:
            dd = defaultdict(list)
            for dc in map(etree_to_dict, children):
                for k, v in dc.items():
                    dd[k].append(v)
            d = {t.tag: {k:v[0] if len(v) == 1 else v for k, v in dd.items()}}
        if t.text:
            text = t.text.strip()
            if children or t.attrib:
                if text:
                  d[t.tag]['#text'] = text
            else:
                d[t.tag] = text
        return d

    data_by_basename = defaultdict(list)

    with zipfile.ZipFile(zip_path, 'r') as zip_ref:
        for file in zip_ref.namelist():
            if file.endswith('.xml'):
                with zip_ref.open(file) as f:
                    tree = ET.parse(f)
                    xml_data = etree_to_dict(tree.getroot())
                    basename = file.rsplit('/')[-1].rsplit('.', 1)[0]
                    data_by_basename[basename].append(xml_data)

    return dict(data_by_basename)

