    lines.append('  ' * indent + self.__class__.__name__ + '(')
    for key, value in self.__dict__.items():
        if isinstance(value, list):
            lines.append('  ' * (indent + 1) + key + '=')
            for item in value:
                lines.append('  ' * (indent + 2) + str(item))
        else:
            lines.append('  ' * (indent + 1) + key + '=' + str(value))
    lines.append('  ' * indent + ')')
    return '\n'.join(lines)

