def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """

    if version.isnumeric():
        return str(int(version) + 1)
    else:
        version_parts = version.rsplit('.', 1)
        version_base = version_parts[0]
        version_suffix = version_parts[1] if len(version_parts) == 2 else ''
        version_number = int(version_suffix.lstrip('0')) if version_suffix else 0
        return f"{version_base}.{version_number + 1}"

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if version:
        parts = version.split('.')
        if len(parts) == 2:
            major, minor = parts
            if minor.isdigit():
                return '.'.join((major, str(int(minor) + 1)))
    return '1.0'

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    root_inventory = {}
    content_digests = {}

    for version_dir in version_dirs:
        version_path = os.path.join(self.root_dir, version_dir)
        inventory_path = os.path.join(version_path, 'inventory.txt')

        if not os.path.exists(inventory_path):
            raise ValueError(f"Inventory file missing for version: {version_dir}")

        with open(inventory_path, 'r') as file:
            for line in file:
                line = line.strip()
                if not line:
                    continue
                inventory_item, digest = line.split(':')
                inventory_item = inventory_item.strip()
                digest = digest.strip()

                if version_dir == '1':
                    root_inventory[inventory_item] = digest
                else:
                    if inventory_item in root_inventory and root_inventory[inventory_item] != digest:
                        content_digests[inventory_item] = digest

    return content_digests

