def deep_merge_nodes(nodes):
    merged = {}

    for key, value in nodes:
        if key.value not in merged:
            merged[key.value] = value
        else:
            if not isinstance(merged[key.value], ruamel.yaml.nodes.MappingNode) or not isinstance(value, ruamel.yaml.nodes.MappingNode):
                merged[key.value] = value
            else:
                merged_value_mapping = merged[key.value].value
                value_mapping = value.value

                for sub_key, sub_value in value_mapping:
                    if sub_key.value not in merged_value_mapping:
                        merged_value_mapping.append((sub_key, sub_value))
                    else:
                        if not isinstance(merged_value_mapping[sub_key.value], ruamel.yaml.nodes.MappingNode) or not isinstance(sub_value, ruamel.yaml.nodes.MappingNode):
                            merged_value_mapping[sub_key.value] = sub_value
                        else:
                            merged_value_mapping[sub_key.value] = deep_merge_nodes([(merged_value_mapping[sub_key.value], sub_value)])

    return [(key, merged[key]) for key in merged]

