def merge_mappings(mapping1, mapping2):
    merged = list(mapping1)
    for key_node, value_node in mapping2:
        for i, (existing_key_node, existing_value_node) in enumerate(merged):
            if existing_key_node.value == key_node.value:
                if isinstance(value_node, MappingNode):
                    merged[i] = (existing_key_node, merge_mappings(existing_value_node.value, value_node.value))
                else:
                    merged[i] = (existing_key_node, value_node)
                break
        else:
            merged.append((key_node, value_node))
    return merged
