                parsed_args = subparser.parse_known_args([arg])
                if parsed_args[0].__dict__ != {'_theonewith': False}:
                    parsed_results[name] = parsed_args[0]
                    unparsed_arguments.remove(arg)
                    break
            except SystemExit:
                # Ignore SystemExit exception so that remaining arguments can be parsed by other subparsers
                pass
        else:
            remaining_arguments.append(arg)

    return parsed_results, remaining_arguments

def parse_subparser_arguments(unparsed_arguments, subparsers):
    """Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser instance, give each requested action's subparser a shot at parsing all arguments. This allows common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of arguments, a list of remaining arguments not claimed by any subparser).
    """
    parsed_args = {subparser_name: None for subparser_name in subparsers}
    remaining_args = list(unparsed_arguments)

    for subparser_name, subparser in subparsers.items():
        arg_iterator = iter(remaining_args)
        try:
            namespace, consumed_args = subparser.parse_known_args(arg_iterator)
            parsed_args[subparser_name] = namespace
            remaining_args = consumed_args
        except SystemExit:
            continue

    return parsed_args, remaining_args

