        for attr, type in iface.REQUIRED_ATTRIBS:
            if not hasattr(candidate, attr):
                mismatch.append(attr)
        for method, doparam, returns in iface.REQUIRED_METHODS:
            if not callable(getattr(candidate, method, None)):
                mismatch.append(method)
        for attr, type in iface.REQUIRED_SKIPPED_ATTRIBS:
            if hasattr(candidate, attr):
                mismatch.append(attr)
