def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    import re
    from typing import Set, Tuple

    def code_block_splitter(text):
        code_re = re.compile('(```[\s\S]*?```|`[^`]*`)')
        return code_re.split(text)

    def find_tags_in_segment(segment):
        if '```' not in segment:
            # No code blocks, simple case
            return re.findall(r'\b\w+\b', segment), segment
        else:
            words = []
            replaced_text = ''
            for part in segment.split('`'):
                if part:
                    if part.startswith('\n'):
                        words.extend(['`', part[1:]])
                        replaced_text += '```\n'
                    elif part.endswith('\n'):
                        words.extend([part[:-1], '`'])
                        replaced_text += part[:-1] + '```\n'
                    else:
                        words.extend(part.split('\n'))
                        replaced_text += part.split('\n')
                else:
                    words.append(part)
                    replaced_text += '```'

            all_tags = set(word for word in words if re.match(r'\b\w+\b', word))
            if replacer:
                replaced_text = ''.join(replacer(word) if re.match(r'\b\w+\b', word) else word for word in replaced_text.split())

            return all_tags, replaced_text

    all_tags = set()
    replaced_text = ''
    for segment in code_block_splitter(text):
        segment_tags, segment_text = find_tags_in_segment(segment)
        all_tags.update(segment_tags)
        replaced_text += segment_text

    return all_tags, replaced_text

def find_tags(text: str, replacer: Optional[Callable] = None) -> Tuple[Set[str], str]:
    tags = set()
    in_code_block = False
    replaced_text = []
    current_tag = ""

    for char in text:
        if char == '`' and not in_code_block:
            in_code_block = True
        elif char == '`' and in_code_block:
            in_code_block = False
        elif in_code_block:
            replaced_text.append(char)
        else:
            if char == '<':
                current_tag =("<")
            elif char == '>':
                current_tag +=(">")
                if current_tag.startswith("<") and current_tag.endswith(">"):
                    tags.add(current_tag)
                    replaced_text.append(current_tag if replacer is None else replacer(current_tag))
                    current_tag = ""
            else:
                if current_tag:
                    current_tag +=(char)
                replaced_text.append(char)

    return (tags, "".join(replaced_text))

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    result = []
    in_code_block = False

    for word in text.split():
        if word.startswith('`') and word.endswith('`'):
            in_code_block = not in_code_block
            result.append(word)
            continue

        if in_code_block:
            result.append(word)
            continue

        if word.startswith('<') and word.endswith('>'):
            tags.add(word)
            if replacer:
                result.append(replacer(word))
            else:
                result.append(word)
        else:
            result.append(word)

    return tags, ' '.join(result)

