from xml.etree import ElementTree as ET

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """

    if document_path is None:
        document_path = os.path.join(url, '.well-known/nodeinfo')

    nodeinfo = {
        "version": "2.0",
        "software": {
            "name": "FoLiAViewer",
            "version": "1.0"
        },
        "protocols": ["activitypub"],
        "services": {
            "inbound": [],
            "outbound": []
        },
        "open_registrations": False,
        "usage": {
            "users": {
                "total": 0
            },
            "localPosts": 0,
            "localComments": 0
        },
        "version": "2.0"
    }

    root = ET.Element("root")
    for key, value in nodeinfo.items():
        if isinstance(value, dict):
            sub_element = ET.SubElement(root, key)
            for sub_key, sub_value in value.items():
                sub_sub_element = ET.SubElement(sub_element, sub_key)
                sub_sub_element.text = str(sub_value)
        else:
            element = ET.SubElement(root, key)
            element.text = str(value)

    tree = ET.ElementTree(root)
    tree.write(document_path, encoding='utf-8', xml_declaration=True)

    return nodeinfo
