def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    from xml.etree import ElementTree as ET
    import json

    try:
        parsed_document = json.loads(document)
        return parsed_document
    except json.JSONDecodeError:
        root = ET.fromstring(document)
        webfinger = {}
        for element in root.findall('./{http://docs.oasis-open.org/ns/xri/xrd-1.0}XRD/{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link'):
            rel = element.get('rel')
            href = element.get('href')
            if rel and href:
                if rel not in webfinger:
                    webfinger[rel] = []
                webfinger[rel].append(href)
        return webfinger
