def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    if spec_option == 'include':
        file_names = []
        for dir in settings_dirs:
            if os.path.exists(dir):
                for root, dirs, files in os.walk(dir):
                    for file in files:
                        if file.endswith('.ini'):
                            file_names.append(os.path.join(root, file))
        return file_names
    elif spec_option == 'exclude':
        exclude_dirs = [os.path.join(root, dir) for dir in settings_dirs for root, _, _ in os.walk('.')]
        file_names = []
        for root, dirs, files in os.walk('.'):
            for file in files:
                if file.endswith('.ini'):
                    if not any(exclude_dir in root for exclude_dir in exclude_dirs):
                        file_names.append(os.path.join(root, file))
        return file_names
    else:
        return []
