    import yaml
    from irvalidator.exceptions import IRValidatorException

    if not spec_content:
        raise IRValidatorException("No content provided for validation.")

    try:
        loaded_data = yaml.safe_load(spec_content)
    except yaml.YAMLError as e:
        raise IRValidatorException(f"Error parsing YAML: {e}")

    required_fields = set(cls.REQUIRED_FIELDS)  # Assuming REQUIRED_FIELDS is defined as a class attribute

